class CircuitBreaker: threshold: int, reset_secs: int _failures: dict[str, int] _opened_at: dict[str, float] def record_failure(engine_name) → opens circuit after threshold def record_success(engine_name) → closes circuit def is_open(engine_name) → bool (auto half-open after reset_secs)
class ElevenLabsQuotaTracker: Redis-backed: key "quota:elevenlabs:YYYY-MM-DD" → char count daily_cap: int (0 = unlimited) async count_chars(n: int) → raises QuotaExceededError if over cap async status() → { used, cap, remaining }
class TTSChain: def __init__(engines: list[BaseTTS], breaker: CircuitBreaker, quota: ElevenLabsQuotaTracker) async synthesize(text, params: TTSParams) → bytes try each engine in fallback_order, skip if circuit open or quota exceeded record_failure / record_success on each attempt async stream_synthesize(text, params) → AsyncGenerator[bytes] same logic, streaming variant def engine_status() → dict[str, str] # closed|open|half-open per engine def primary_engine_name() → str # first closed engine
def build_tts_chain(tts_cfg: TtsConfig, redis) → TTSChain: # Factory: đọc fallback_order từ config, khởi tạo engines tương ứng # Replaces _build_tts() và _build_tts_forced() trong ws.py

class ConversationEngine: def __init__(ollama_base_url, model, system_prompt, temperature, max_history_turns)
async def stream_response( utterance: str, kb_context: str | None, # KB answer làm grounding fact history: list[tuple[str,str]], # [(user_text, agent_text), ...] emotion: EmotionState, ) → AsyncGenerator[str, None]: # yield tokens # Build messages: # [system] persona + constraint (không bịa ngoài kb_context) # [system-inject nếu emotion!=neutral] "KH đang {emotion}, hãy nhẹ nhàng/..." # [user/assistant alternating] last N turns từ history # [user] kb_context + utterance # POST ollama /v1/chat/completions stream=True # yield content tokens
def _build_system(self, emotion: EmotionState) → str: base = self.system_prompt if emotion.label in ("frustrated","angry"): base += "\nKhách đang không hài lòng. Hãy nhẹ nhàng, thông cảm, không vội." elif emotion.label == "confused": base += "\nKhách đang chưa hiểu rõ. Giải thích rõ ràng, ngắn gọn từng bước." return base

modify_file.add:
SessionState thêm field: emotion_history: tuple[str, ...] = field(default_factory=tuple)

def with_emotion(self, label: str, max_keep: int = 5) → SessionState:
  return replace(self, emotion_history=(*self.emotion_history[-(max_keep-1):], label))

def current_emotion(self) → str:
  # majority vote trong 3 turns gần nhất, default "neutral"
  recent = self.emotion_history[-3:]
  if not recent: return "neutral"
  return max(set(recent), key=recent.count)

